pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 ticketCount) public {
        ticketCount = bound(ticketCount, 1, 10);
        uint256 totalSent = 0;
        uint256 totalPaid = 0;

        vm.deal(address(this), ticketCount * 10 ether);
        for (uint256 i = 0; i < ticketCount; i++) {
            uint256 snapshotPot = c.pot();
            uint256 snapshotBalance = address(c).balance;

            c.play{value: 10}();

            totalSent += 10;
            if (c.pot() < snapshotPot) {
                totalPaid += snapshotPot;
            }
        }

        assertEq(c.pot(), totalSent - totalPaid, "pot must equal net tickets minus payouts");
    }
}
